{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js",
    "test": "node --test"
  }
}
import { createServer } from 'node:http';
import { readFileSync } from 'node:fs';
import { openProjects } from './projects.js';
import { projectsPage, projectPage, notFoundPage } from './views.js';
import { normalizeSearchQuery } from './search.js';
import { TASK_PRIORITIES } from './task-priorities.js';
import { normalizeDueDate, normalizeDueRange, INVALID_DUE_DATE_MESSAGE } from './task-dates.js';

const projects = openProjects(process.env.DB_PATH || 'data/workboard.sqlite');
const stylesheet = readFileSync(new URL('./public/styles.css', import.meta.url));
const formScript = readFileSync(new URL('./public/forms.js', import.meta.url));

function taskFilter(value) {
  return ['All', 'Open', 'Completed'].includes(value) ? value : 'All';
}

function priorityFilter(value) {
  return TASK_PRIORITIES.includes(value) ? value : 'All';
}

function projectFilters(parameters) {
  const range = normalizeDueRange(parameters.get('dueFrom') || '', parameters.get('dueThrough') || '');
  return {
    search: normalizeSearchQuery(parameters.get('search') || ''),
    completion: taskFilter(parameters.get('filter')),
    priority: priorityFilter(parameters.get('priorityFilter')),
    dueFrom: range.dueFrom || '',
    dueThrough: range.dueThrough || '',
  };
}

function renderProject(project, filters, error = '') {
  return projectPage(project, projects.listTasks(project.id, filters.completion, filters.priority, filters),
    filters.completion, error, filters.priority, filters,
    projects.list().filter((destination) => destination.id !== project.id));
}

function projectLocation(projectId, filters) {
  const query = new URLSearchParams({ filter: filters.completion });
  if (filters.priority !== 'All') query.set('priorityFilter', filters.priority);
  if (filters.dueFrom) query.set('dueFrom', filters.dueFrom);
  if (filters.dueThrough) query.set('dueThrough', filters.dueThrough);
  if (filters.search) query.set('search', filters.search);
  return `/projects/${projectId}?${query}`;
}

function projectsLocation(filter, search) {
  const query = new URLSearchParams();
  if (filter !== 'Active') query.set('filter', filter);
  if (search) query.set('search', search);
  return query.size ? `/?${query}` : '/';
}

function projectFilter(value) {
  return value === 'Archived' ? 'Archived' : 'Active';
}

function redirect(response, location) {
  response.writeHead(303, { Location: location });
  response.end();
}

function send(response, status, type, body) {
  response.writeHead(status, { 'Content-Type': type, 'X-Content-Type-Options': 'nosniff' });
  response.end(body);
}

async function readForm(request) {
  const chunks = [];
  let size = 0;
  for await (const chunk of request) {
    size += chunk.length;
    if (size > 64 * 1024) {
      const error = new Error('Request too large');
      error.status = 413;
      throw error;
    }
    chunks.push(chunk);
  }
  return new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
}

const server = createServer(async (request, response) => {
  try {
    const url = new URL(request.url, 'http://localhost');
    const path = url.pathname;
    if (request.method === 'GET' && path === '/health') {
      return send(response, 200, 'application/json', JSON.stringify({ status: 'ok' }));
    }
    if (request.method === 'GET' && path === '/styles.css') {
      return send(response, 200, 'text/css; charset=utf-8', stylesheet);
    }
    if (request.method === 'GET' && path === '/forms.js') {
      return send(response, 200, 'text/javascript; charset=utf-8', formScript);
    }
    if (request.method === 'GET' && path === '/') {
      const filter = projectFilter(url.searchParams.get('filter'));
      const search = normalizeSearchQuery(url.searchParams.get('search') || '');
      return send(response, 200, 'text/html; charset=utf-8', projectsPage(projects.list(filter, search), '', filter, search));
    }
    if (request.method === 'POST' && path === '/projects') {
      const form = await readForm(request);
      const filter = projectFilter(form.get('filter'));
      const search = normalizeSearchQuery(form.get('search') || '');
      if (!projects.create(form.get('name') || '')) {
        return send(response, 400, 'text/html; charset=utf-8',
          projectsPage(projects.list(filter, search), 'Project name is required', filter, search));
      }
      return redirect(response, projectsLocation(filter, search));
    }
    const archiveMatch = path.match(/^\/projects\/([1-9]\d*)\/(archive|restore)$/);
    if (request.method === 'POST' && archiveMatch && Number.isSafeInteger(Number(archiveMatch[1]))) {
      const form = await readForm(request);
      if (projects.setArchived(Number(archiveMatch[1]), archiveMatch[2] === 'archive')) {
        const filter = projectFilter(form.get('filter') || (archiveMatch[2] === 'restore' ? 'Archived' : 'Active'));
        const search = normalizeSearchQuery(form.get('search') || '');
        return redirect(response, projectsLocation(filter, search));
      }
    }
    const match = path.match(/^\/projects\/([1-9]\d*)$/);
    if (request.method === 'GET' && match && Number.isSafeInteger(Number(match[1]))) {
      const project = projects.find(Number(match[1]));
      if (project) {
        const filters = projectFilters(url.searchParams);
        return send(response, 200, 'text/html; charset=utf-8',
          renderProject(project, filters));
      }
    }
    const dueRangeMatch = path.match(/^\/projects\/([1-9]\d*)\/due-range$/);
    if (request.method === 'POST' && dueRangeMatch && Number.isSafeInteger(Number(dueRangeMatch[1]))) {
      const project = projects.find(Number(dueRangeMatch[1]));
      if (project) {
        const form = await readForm(request);
        const filters = projectFilters(form);
        const range = normalizeDueRange(form.get('rangeFrom') || '', form.get('rangeThrough') || '');
        if (range.error) {
          return send(response, 400, 'text/html; charset=utf-8', renderProject(project, filters, range.error));
        }
        return redirect(response, projectLocation(project.id, { ...filters, ...range }));
      }
    }
    const defaultPriorityMatch = path.match(/^\/projects\/([1-9]\d*)\/default-priority$/);
    if (request.method === 'POST' && defaultPriorityMatch && Number.isSafeInteger(Number(defaultPriorityMatch[1]))) {
      const project = projects.find(Number(defaultPriorityMatch[1]));
      if (project) {
        if (project.archived) {
          return send(response, 409, 'text/plain; charset=utf-8', 'Archived project');
        }
        const form = await readForm(request);
        const filters = projectFilters(form);
        if (!projects.setDefaultTaskPriority(project.id, form.get('priority'))) {
          return send(response, 400, 'text/html; charset=utf-8',
            renderProject(project, filters, 'Invalid task priority'));
        }
        return redirect(response, projectLocation(project.id, filters));
      }
    }
    const renameMatch = path.match(/^\/projects\/([1-9]\d*)\/rename$/);
    if (request.method === 'POST' && renameMatch && Number.isSafeInteger(Number(renameMatch[1]))) {
      const project = projects.find(Number(renameMatch[1]));
      if (project) {
        if (project.archived) {
          return send(response, 409, 'text/plain; charset=utf-8', 'Archived project');
        }
        const form = await readForm(request);
        const filters = projectFilters(form);
        if (!projects.rename(project.id, form.get('name') || '')) {
          return send(response, 400, 'text/html; charset=utf-8',
            renderProject(project, filters, 'Project name is required'));
        }
        return redirect(response, projectLocation(project.id, filters));
      }
    }
    const taskMatch = path.match(/^\/projects\/([1-9]\d*)\/tasks(?:\/([1-9]\d*)\/(completion|rename|priority|due-date|notes|move))?$/);
    if (request.method === 'POST' && taskMatch &&
        Number.isSafeInteger(Number(taskMatch[1])) &&
        (!taskMatch[2] || Number.isSafeInteger(Number(taskMatch[2])))) {
      const project = projects.find(Number(taskMatch[1]));
      if (project) {
        if (project.archived) {
          return send(response, 409, 'text/plain; charset=utf-8', 'Archived project');
        }
        const form = await readForm(request);
        const filters = projectFilters(form);
        if (taskMatch[3] === 'notes') {
          if (!projects.setTaskNotes(project.id, Number(taskMatch[2]), form.get('notes') || '')) {
            return send(response, 404, 'text/html; charset=utf-8', notFoundPage());
          }
        } else if (taskMatch[3] === 'move') {
          const destination = form.get('destination');
          if (!/^[1-9]\d*$/.test(destination || '') ||
              !projects.moveTask(project.id, Number(taskMatch[2]), Number(destination))) {
            return send(response, 400, 'text/html; charset=utf-8',
              renderProject(project, filters, 'Task cannot be moved to that project'));
          }
        } else if (taskMatch[3] === 'rename') {
          const title = (form.get('title') || '').trim();
          if (!title) {
            return send(response, 400, 'text/html; charset=utf-8',
              renderProject(project, filters, 'Task title is required'));
          }
          if (!projects.renameTask(project.id, Number(taskMatch[2]), title)) {
            return send(response, 404, 'text/html; charset=utf-8', notFoundPage());
          }
        } else if (taskMatch[3] === 'priority') {
          const priority = form.get('priority');
          if (!TASK_PRIORITIES.includes(priority)) {
            return send(response, 400, 'text/html; charset=utf-8',
              renderProject(project, filters, 'Invalid task priority'));
          }
          if (!projects.setTaskPriority(project.id, Number(taskMatch[2]), priority)) {
            return send(response, 404, 'text/html; charset=utf-8', notFoundPage());
          }
        } else if (taskMatch[3] === 'due-date') {
          const date = normalizeDueDate(form.get('dueDate') || '');
          if (date === null) {
            return send(response, 400, 'text/html; charset=utf-8',
              renderProject(project, filters, INVALID_DUE_DATE_MESSAGE));
          }
          if (!projects.setTaskDueDate(project.id, Number(taskMatch[2]), date)) {
            return send(response, 404, 'text/html; charset=utf-8', notFoundPage());
          }
        } else if (taskMatch[2]) {
          if (!projects.setTaskCompleted(project.id, Number(taskMatch[2]), form.has('completed'))) {
            return send(response, 404, 'text/html; charset=utf-8', notFoundPage());
          }
        } else if (!projects.createTask(project.id, form.get('title') || '')) {
          return send(response, 400, 'text/html; charset=utf-8',
            renderProject(project, filters, 'Task title is required'));
        }
        return redirect(response, projectLocation(project.id, filters));
      }
    }
    send(response, 404, 'text/html; charset=utf-8', notFoundPage());
  } catch (error) {
    if (!error.status) console.error(error);
    send(response, error.status || 500, 'text/plain; charset=utf-8',
      error.status ? error.message : 'Internal server error');
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0', () => {
  console.log(`Workboard listening on port ${server.address().port}`);
});

for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => {
    server.close(() => {
      projects.close();
      process.exit(0);
    });
  });
}
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import { matchesSearch } from './search.js';
import { TASK_PRIORITIES } from './task-priorities.js';
import { normalizeDueDate } from './task-dates.js';

export function openProjects(databasePath) {
  mkdirSync(dirname(databasePath), { recursive: true });
  const database = new DatabaseSync(databasePath);
  database.exec('PRAGMA foreign_keys = ON');
  database.exec(`
    CREATE TABLE IF NOT EXISTS projects (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL CHECK(length(trim(name)) > 0)
    );
    CREATE TABLE IF NOT EXISTS tasks (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      project_id INTEGER NOT NULL REFERENCES projects(id),
      title TEXT NOT NULL CHECK(length(trim(title)) > 0),
      completed INTEGER NOT NULL DEFAULT 0 CHECK(completed IN (0, 1))
    );
    CREATE INDEX IF NOT EXISTS tasks_project_id ON tasks(project_id);
  `);
  if (!database.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'archived')) {
    database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0, 1))');
  }
  if (!database.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'priority')) {
    database.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK(priority IN ('Low', 'Normal', 'High'))");
  }
  if (!database.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'default_task_priority')) {
    database.exec("ALTER TABLE projects ADD COLUMN default_task_priority TEXT NOT NULL DEFAULT 'Normal' CHECK(default_task_priority IN ('Low', 'Normal', 'High'))");
  }
  if (!database.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'due_date')) {
    database.exec("ALTER TABLE tasks ADD COLUMN due_date TEXT NOT NULL DEFAULT ''");
  }
  if (!database.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'notes')) {
    database.exec("ALTER TABLE tasks ADD COLUMN notes TEXT NOT NULL DEFAULT ''");
  }
  // Legacy databases used tasks.position, or task IDs before movement existed.
  // Seed only current memberships; earlier moves cannot be reconstructed.
  const hasLegacyPosition = database.prepare('PRAGMA table_info(tasks)').all()
    .some((column) => column.name === 'position');
  database.exec(`
    BEGIN;
    CREATE TABLE IF NOT EXISTS task_project_positions (
      task_id INTEGER NOT NULL REFERENCES tasks(id),
      project_id INTEGER NOT NULL REFERENCES projects(id),
      position INTEGER NOT NULL,
      PRIMARY KEY (task_id, project_id),
      UNIQUE (project_id, position)
    );
    INSERT INTO task_project_positions (task_id, project_id, position)
      SELECT id, project_id, ${hasLegacyPosition ? 'position' : 'id'} FROM tasks
      WHERE NOT EXISTS (
        SELECT 1 FROM task_project_positions
        WHERE task_id = tasks.id AND project_id = tasks.project_id
      );
    COMMIT;
  `);

  function transaction(operation) {
    database.exec('BEGIN');
    try {
      const result = operation();
      database.exec('COMMIT');
      return result;
    } catch (error) {
      database.exec('ROLLBACK');
      throw error;
    }
  }
  const list = database.prepare(`
    SELECT projects.id, projects.name, projects.archived,
      COUNT(tasks.id) AS total_count, COALESCE(SUM(tasks.completed), 0) AS completed_count
    FROM projects LEFT JOIN tasks ON tasks.project_id = projects.id
    WHERE projects.archived = ? GROUP BY projects.id ORDER BY projects.id
  `);
  const find = database.prepare('SELECT id, name, archived, default_task_priority FROM projects WHERE id = ?');
  const insert = database.prepare('INSERT INTO projects (name) VALUES (?)');
  const updateArchive = database.prepare('UPDATE projects SET archived = ? WHERE id = ?');
  const updateName = database.prepare('UPDATE projects SET name = ? WHERE id = ? AND archived = 0');
  const updateDefaultPriority = database.prepare('UPDATE projects SET default_task_priority = ? WHERE id = ? AND archived = 0');
  const listTasks = database.prepare(`
    SELECT tasks.id, title, completed, priority, due_date, notes FROM tasks
    JOIN task_project_positions AS ordering
      ON ordering.task_id = tasks.id AND ordering.project_id = tasks.project_id
    WHERE tasks.project_id = ? AND (? IS NULL OR completed = ?)
      AND (? IS NULL OR priority = ?)
      AND (? = '' OR due_date >= ?)
      AND (? = '' OR (due_date != '' AND due_date <= ?)) ORDER BY ordering.position, tasks.id
  `);
  const insertTask = database.prepare(`
    INSERT INTO tasks (project_id, title, priority)
    SELECT id, ?, default_task_priority FROM projects WHERE id = ? AND archived = 0
  `);
  const rememberPosition = database.prepare(`
    INSERT INTO task_project_positions (task_id, project_id, position)
    VALUES (?, ?, (SELECT COALESCE(MAX(position), 0) + 1
      FROM task_project_positions WHERE project_id = ?))
  `);
  const updateTask = database.prepare(`
    UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?
      AND EXISTS (SELECT 1 FROM projects WHERE id = tasks.project_id AND archived = 0)
  `);
  const updateTaskTitle = database.prepare(`
    UPDATE tasks SET title = ? WHERE id = ? AND project_id = ?
      AND EXISTS (SELECT 1 FROM projects WHERE id = tasks.project_id AND archived = 0)
  `);
  const updateTaskPriority = database.prepare(`
    UPDATE tasks SET priority = ? WHERE id = ? AND project_id = ?
      AND EXISTS (SELECT 1 FROM projects WHERE id = tasks.project_id AND archived = 0)
  `);
  const updateTaskDueDate = database.prepare(`
    UPDATE tasks SET due_date = ? WHERE id = ? AND project_id = ?
      AND EXISTS (SELECT 1 FROM projects WHERE id = tasks.project_id AND archived = 0)
  `);
  const updateTaskNotes = database.prepare(`
    UPDATE tasks SET notes = ? WHERE id = ? AND project_id = ?
      AND EXISTS (SELECT 1 FROM projects WHERE id = tasks.project_id AND archived = 0)
  `);
  const eligibleMove = database.prepare(`
    SELECT tasks.id FROM tasks
    JOIN projects AS source ON source.id = tasks.project_id
    JOIN projects AS destination ON destination.id = ?
    WHERE tasks.id = ? AND tasks.project_id = ? AND source.id != destination.id
      AND source.archived = 0 AND destination.archived = 0
  `);
  const findPosition = database.prepare(`
    SELECT position FROM task_project_positions WHERE task_id = ? AND project_id = ?
  `);
  const moveTask = database.prepare('UPDATE tasks SET project_id = ? WHERE id = ?');

  return {
    list: (filter = 'Active', search = '') => list.all(filter === 'Archived' ? 1 : 0)
      .filter((project) => matchesSearch(project.name, search)),
    find: (id) => find.get(id),
    setArchived(id, archived) {
      return updateArchive.run(archived ? 1 : 0, id).changes > 0;
    },
    create(name) {
      const trimmedName = name.trim();
      if (!trimmedName) return false;
      insert.run(trimmedName);
      return true;
    },
    rename(id, name) {
      const trimmedName = name.trim();
      if (!trimmedName) return false;
      return updateName.run(trimmedName, id).changes > 0;
    },
    setDefaultTaskPriority(id, priority) {
      if (!TASK_PRIORITIES.includes(priority)) return false;
      return updateDefaultPriority.run(priority, id).changes > 0;
    },
    listTasks(projectId, filter = 'All', priorityFilter = 'All', dueRange = {}) {
      const completed = filter === 'Open' ? 0 : filter === 'Completed' ? 1 : null;
      const priority = TASK_PRIORITIES.includes(priorityFilter) ? priorityFilter : null;
      const { dueFrom = '', dueThrough = '', search = '' } = dueRange;
      return listTasks.all(projectId, completed, completed, priority, priority,
        dueFrom, dueFrom, dueThrough, dueThrough)
        .filter((task) => matchesSearch(task.title, search));
    },
    createTask(projectId, title) {
      const trimmedTitle = title.trim();
      if (!trimmedTitle) return false;
      return transaction(() => {
        const inserted = insertTask.run(trimmedTitle, projectId);
        if (!inserted.changes) return false;
        rememberPosition.run(inserted.lastInsertRowid, projectId, projectId);
        return true;
      });
    },
    setTaskCompleted(projectId, taskId, completed) {
      return updateTask.run(completed ? 1 : 0, taskId, projectId).changes > 0;
    },
    renameTask(projectId, taskId, title) {
      const trimmedTitle = title.trim();
      if (!trimmedTitle) return false;
      return updateTaskTitle.run(trimmedTitle, taskId, projectId).changes > 0;
    },
    setTaskPriority(projectId, taskId, priority) {
      if (!TASK_PRIORITIES.includes(priority)) return false;
      return updateTaskPriority.run(priority, taskId, projectId).changes > 0;
    },
    setTaskDueDate(projectId, taskId, value) {
      const date = normalizeDueDate(value);
      if (date === null) return false;
      return updateTaskDueDate.run(date, taskId, projectId).changes > 0;
    },
    setTaskNotes(projectId, taskId, notes) {
      return updateTaskNotes.run(notes, taskId, projectId).changes > 0;
    },
    moveTask(projectId, taskId, destinationId) {
      if (!Number.isSafeInteger(destinationId) || destinationId < 1) return false;
      return transaction(() => {
        if (!eligibleMove.get(destinationId, taskId, projectId)) return false;
        if (!findPosition.get(taskId, destinationId)) {
          rememberPosition.run(taskId, destinationId, destinationId);
        }
        moveTask.run(destinationId, taskId);
        return true;
      });
    },
    close: () => database.close(),
  };
}

import { TASK_PRIORITIES } from './task-priorities.js';

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, (character) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  })[character]);
}

function textareaContent(value) {
  // HTML parsing discards one initial newline inside a textarea. Supply that
  // newline explicitly so a saved leading newline remains part of the value.
  return `\n${escapeHtml(value)}`;
}

function page(title, content) {
  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(title)} · Workboard</title>
  <link rel="stylesheet" href="/styles.css">
  <script src="/forms.js" defer></script>
</head>
<body><main>${content}</main></body>
</html>`;
}

export function projectsPage(projects, error = '', filter = 'Active', search = '') {
  return page('Projects', `
    <h1>Workboard</h1>
    <form action="/projects" method="post" class="create-project">
      <input type="hidden" name="filter" value="${escapeHtml(filter)}">
      <input type="hidden" name="search" value="${escapeHtml(search)}">
      <label for="project-name">Project name</label>
      <div class="form-controls">
        <input id="project-name" name="name" type="text" autocomplete="off">
        <button type="submit">Create project</button>
      </div>
    </form>
    ${error ? `<p role="alert">${escapeHtml(error)}</p>` : ''}
    <form action="/" method="get" class="project-filter" data-auto-submit>
      <input type="hidden" name="search" value="${escapeHtml(search)}">
      <label for="project-filter">Project filter</label>
      <select id="project-filter" name="filter">
        ${['Active', 'Archived'].map((option) =>
          `<option${option === filter ? ' selected' : ''}>${option}</option>`).join('')}
      </select>
    </form>
    <form action="/" method="get" class="project-search">
      <input type="hidden" name="filter" value="${escapeHtml(filter)}">
      <label for="project-search">Project search</label>
      <div class="form-controls">
        <input id="project-search" name="search" type="text" value="${escapeHtml(search)}" autocomplete="off">
        <button type="submit">Search projects</button>
      </div>
    </form>
    <section aria-label="Projects" class="project-list">
      ${projects.length ? projects.map((project) => `
        <div data-testid="project-row" class="project-row">
          <span>${escapeHtml(project.name)}</span>
          <span data-testid="project-summary">${project.completed_count}/${project.total_count} completed</span>
          <form action="/projects/${project.id}" method="get">
            <button type="submit">Open project</button>
          </form>
          <form action="/projects/${project.id}/${project.archived ? 'restore' : 'archive'}" method="post">
            <input type="hidden" name="filter" value="${escapeHtml(filter)}">
            <input type="hidden" name="search" value="${escapeHtml(search)}">
            <button type="submit">${project.archived ? 'Restore project' : 'Archive project'}</button>
          </form>
        </div>`).join('') : '<p class="empty">Your projects will appear here.</p>'}
    </section>`);
}

export function projectPage(project, tasks = [], filter = 'All', error = '', priorityFilter = 'All', dueRange = {}, destinations = []) {
  const projectPath = `/projects/${project.id}`;
  const moveDisabled = project.archived || !destinations.length;
  const { dueFrom = '', dueThrough = '', search = '' } = dueRange;
  const searchField = `<input type="hidden" name="search" value="${escapeHtml(search)}">`;
  const rangeFields = `
    <input type="hidden" name="dueFrom" value="${escapeHtml(dueFrom)}">
    <input type="hidden" name="dueThrough" value="${escapeHtml(dueThrough)}">`;
  const otherFilterFields = `
    <input type="hidden" name="filter" value="${escapeHtml(filter)}">
    <input type="hidden" name="priorityFilter" value="${escapeHtml(priorityFilter)}">
    ${rangeFields}`;
  const filterFields = `${otherFilterFields}${searchField}`;
  return page(project.name, `
    <form action="/" method="get"><button type="submit">Projects</button></form>
    <h1>${escapeHtml(project.name)}</h1>
    ${project.archived ? '<p>Archived project</p>' : ''}
    <form action="${projectPath}/rename" method="post">
      ${filterFields}
      <label for="new-project-name">New project name</label>
